import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const packageRoot = fileURLToPath(new URL("..", import.meta.url));
const outputUrl = new URL("../src/codemode/generated-content.ts", import.meta.url);
const skill = readFileSync(new URL("../codemode/SKILL.md", import.meta.url), "utf8").trim();
const reference = readFileSync(new URL("../codemode/REFERENCE.md", import.meta.url), "utf8").trim();
const output = [
  "// Generated by scripts/generate-codemode-content.mjs. Do not edit directly.",
  "export const STAGEHAND_CODEMODE_SKILL =",
  `  ${singleQuotedString(skill)};`,
  "export const STAGEHAND_CODEMODE_REFERENCE =",
  `  ${singleQuotedString(reference)};`,
  "",
].join("\n");

if (process.argv.includes("--check")) {
  const generated = readFileSync(outputUrl, "utf8");
  if (generated !== output) {
    throw new Error(`Generated code-mode content is stale. Run "pnpm generate" in ${packageRoot}.`);
  }
  process.stdout.write("Generated code-mode content is current\n");
} else {
  writeFileSync(outputUrl, output);
  process.stdout.write(`Generated code-mode content in ${packageRoot}\n`);
}

function singleQuotedString(value) {
  return `'${value
    .replaceAll("\\", "\\\\")
    .replaceAll("'", "\\'")
    .replaceAll("\r", "\\r")
    .replaceAll("\n", "\\n")
    .replaceAll("\t", "\\t")
    .replaceAll("\u2028", "\\u2028")
    .replaceAll("\u2029", "\\u2029")}'`;
}
